{
  "claim": "For non-headline hyperscaler list-price series outside the 14-day gate and fewer than 22 days since the last change, drift alone will reduce pinball loss relative to the current system.",
  "mechanism": "The hypothesis is that these published medians move through occasional provider list-price revisions whose sizes and frequency are specific to each series. Using the series' own historical horizon-length changes should better represent those revisions and intervening unchanged prices than forecasts borrowing movement patterns across series.",
  "spec": {
    "when": {
      "all": [
        {"fact": "cls", "op": "==", "value": "hyperscaler_list"},
        {"fact": "days_since_change", "op": "<", "value": 22},
        {"fact": "gate14", "op": "==", "value": false},
        {"fact": "in37", "op": "==", "value": false}
      ]
    },
    "do": {
      "action": "members_only",
      "members": ["drift"]
    }
  },
  "falsification": "Reject if pooled skill fails to rise overall or in either selection half, fewer than 200 cells across at least five series change, headline skill falls, or fewer than 90% of the 2000 ISO-week block bootstrap resamples show improvement.",
  "prior_ids_used": [],
  "expects": "A modest pooled skill increase with headline forecasts unchanged. The broader hyperscaler_list slices support the direction: drift skill is +0.247 versus -0.012 for changes within four days, and +0.102 versus -0.025 for four through 21 days. The exact filtered slice, number of changed cells, temporal consistency, and bootstrap acceptance remain unverified."
}
